import{_ as i,H as t,f as l,i as p}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"47 | RESTfulWebServices（11）：如何通过Spike来验证架构愿景？","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾架构愿景与任务列表","slug":"回顾架构愿景与任务列表","link":"#回顾架构愿景与任务列表","children":[]},{"level":2,"title":"通过 Spike 验证架构愿景","slug":"通过-spike-验证架构愿景","link":"#通过-spike-验证架构愿景","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/47｜RESTfulWebServices（11）：如何通过Spike来验证架构愿景？.md","filePath":"徐昊·TDD项目实战70讲/47｜RESTfulWebServices（11）：如何通过Spike来验证架构愿景？.md","lastUpdated":1795563222000}'),a={name:"徐昊·TDD项目实战70讲/47｜RESTfulWebServices（11）：如何通过Spike来验证架构愿景？.md"};function s(r,e,o,n,u,c){return t(),l("div",null,[...e[0]||(e[0]=[p('<h1 id="_47-restfulwebservices-11-如何通过spike来验证架构愿景" tabindex="-1">47 | RESTfulWebServices（11）：如何通过Spike来验证架构愿景？ <a class="header-anchor" href="#_47-restfulwebservices-11-如何通过spike来验证架构愿景" aria-label="Permalink to &quot;47 | RESTfulWebServices（11）：如何通过Spike来验证架构愿景？&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续使用 TDD 的方式实现 RESTful Web Services。</p><h2 id="回顾架构愿景与任务列表" tabindex="-1">回顾架构愿景与任务列表 <a class="header-anchor" href="#回顾架构愿景与任务列表" aria-label="Permalink to &quot;回顾架构愿景与任务列表&quot;">​</a></h2><p>目前，我们的任务列表是这样的：</p><ul><li><p>RuntimeDelegate</p></li><li><p>为 MediaType 提供 HeaderDelegate</p></li><li><p>为 CacheControl 提供 HeaderDelegate</p></li><li><p>为 Cookie 提供 HeaderDelegates</p></li><li><p>为 EntityTag 提供 HeaderDelegate</p></li><li><p>为 Link 提供 HeaderDelegate</p></li><li><p>为 NewCookie 提供 HeaderDelegate</p></li><li><p>为 Date 提供 HeaderDelegate</p></li><li><p>提供 OutboundResponseBuilder</p></li><li><p>OutboundResponseBuilder</p></li><li><p>可按照不同的 Status 生成 Resposne</p></li><li><p>OutboundResponse</p></li><li><p>ResourceDispatcher</p></li><li><p>将 Resource Method 的返回值包装为 Response 对象</p></li><li><p>Providers</p></li><li><p>可获取 MessageBodyWriter</p></li><li><p>可获取 ExceptionMapper</p></li><li><p>Runtimes</p></li><li><p>可获取 ResourceDispatcher</p></li><li><p>可获取 Providers</p></li><li><p>MessageBodyWriter</p></li><li><p>ExceptionMapper</p></li><li><p>需要提供默认的 ExceptionMapper</p></li></ul><h2 id="通过-spike-验证架构愿景" tabindex="-1">通过 Spike 验证架构愿景 <a class="header-anchor" href="#通过-spike-验证架构愿景" aria-label="Permalink to &quot;通过 Spike 验证架构愿景&quot;">​</a></h2><p>上节课我们讨论到，当使用伦敦学派时，能不能直接进入经典模式继续开发，对于如何继续拆分任务起到了关键作用。在目前的任务列表中，ResourceDispatcher 显然难以直接进入经典模式（也不是不可以，如果你对重构足够自信的话，已经算是恰当的粒度了），那么我们可以围绕 ResourceDispatcher 继续构建架构愿景，澄清调用栈，然后采用伦敦学派继续开发。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/47/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/47/1.png" alt=""></a></p><p>如上图所示，是一个非常简单的架构构想：</p><ul><li><p>将所有的 RootResource 的 Path 转化为正则表达式的 Pattern；</p></li><li><p>ResourceRouter 拿到 HttpServletRequest 之后，尝试与 Pattern 匹配；</p></li><li><p>匹配到的 RootResource 通过 Context 实例化；</p></li><li><p>调用实例化后的 RootResource，处理请求，过程中把中间信息存入 UriInfo；</p></li><li><p>ResourceRouter 拿到结果后，转化为 Response 对象返回。</p></li></ul><p>接下来我们需要通过 Spike 验证架构愿景：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/47/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/47/2.jpeg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在进入下节课之前，希望你能认真思考如下两个问题。</p><ol><li><p>要如何调整架构愿景？</p></li><li><p>进入项目三的学习后，你有什么有意思的收获吗？</p></li></ol><p>欢迎把你的想法分享在留言区，也欢迎把你的项目代码分享出来。相信经过你的思考与实操，学习效果会更好！</p>',16)])])}const d=i(a,[["render",s]]);export{h as __pageData,d as default};
